import{_ as t,a as r}from"./chunks/cf64b75a09891e69380c.DG_q5fRd.js";import{_ as i,C as o,o as l,c as n,j as p,a as u,E as s,a6 as m}from"./chunks/framework.CnPv4DE1.js";const A=JSON.parse('{"title":"生产力的未来：用日常安排为不确定的生活建立秩序","description":"","frontmatter":{"title":"生产力的未来：用日常安排为不确定的生活建立秩序","originalTitle":"The Future Of Productivity (A Daily Routine To Organize Your Uncertain Life)","date":"2024-12-21","originalUrl":"https://thedankoe.com/letters/the-future-of-productivity-a-daily-routine-to-organize-your-uncertain-life/","minutes":16,"sourceHash":"820c95b5592f1f6dbbb464268d0dccaa2a3c9a1127ff484314cd3aad5250d5c7","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-future-of-productivity-a-daily-routine-to-organize-your-uncertain-life/"}]]},"headers":[],"relativePath":"letters/the-future-of-productivity-a-daily-routine-to-organize-your-uncertain-life.md","filePath":"letters/the-future-of-productivity-a-daily-routine-to-organize-your-uncertain-life.md"}'),c={name:"letters/the-future-of-productivity-a-daily-routine-to-organize-your-uncertain-life.md"};function h(d,e,f,b,k,_){const a=o("ArticleMeta");return l(),n("div",null,[e[0]||(e[0]=p("h1",{id:"生产力的未来-用日常安排为不确定的生活建立秩序",tabindex:"-1"},[u("生产力的未来：用日常安排为不确定的生活建立秩序 "),p("a",{class:"header-anchor",href:"#生产力的未来-用日常安排为不确定的生活建立秩序","aria-label":'Permalink to "生产力的未来：用日常安排为不确定的生活建立秩序"'},"​")],-1)),s(a),e[1]||(e[1]=m('<blockquote><p><a href="https://www.youtube.com/embed/B18O2QtkyCE?si=MT-Mjbkj4x0Xx8p7" target="_blank" rel="noreferrer">观看原文视频</a></p><p>人们说，聪明人工作得更巧妙，而不是更卖力，但真正有创造力的人根本不“工作”。——亚历克斯·庄（Alex Pang）</p></blockquote><p>很遗憾，普通美国人把过度工作等同于一种身份地位的象征。</p><p>更糟的是，他们把它当作逃避其他责任的方式。</p><p>因为如果你真的认真对待自己的工作，你就会去优化创造力，而不是生产力。你会好好吃饭。每天训练身体。去散步。睡够觉。社交。以有计算的方式挑战自己的极限。并设计一种把心智输入和输出放在优先位置的生活方式。你会明白，4小时专注的工作产出的成果，远高于12小时散乱的工作。</p><p>如果你理解大脑，你就会明白人类和动物有些不同。动物试图复制自己的身体，也就是它们基因编码中的信息。人类也这样做，但我们还试图复制我们的“心智之身”——我们意识中的信息。我们的身份认同。我们写书、与人争论、获取知识，是为了用一些小小的想法去“怀上”别人的心智，让这些想法生根发芽（或腐烂）。</p><p>当过度工作变成了你的身份认同——往往是通过无意识地重复社会强加给你的目标——你会不断地感到焦虑，一旦你“没有在高效工作”就会不安。</p><p>但大多数人对生产力的理解是错的。他们可能不会明确这么说，但他们的行动说明了这一点。他们以为生产力是数量问题，不是质量问题。他们以为一天中所有的时间都是平等的，以为他们在一天最后4个小时和最初4个小时是同一个人。他们以为生产力是要做所有的事，而不是那件能带来全部结果的事。</p><p>他们没能把“任务”和“杠杆”区分开来。他们没意识到，A可以每天工作12小时，年入5万美元，而B可以每天工作1小时，年入500万美元。差别在于技能、杠杆和认知，而不在于你工作得多辛苦、多久、多有条理。</p><p>秘诀在于设计一种创造性的生活方式。以下是这篇文章我们要谈的内容：</p><ul><li>为什么在AI恐慌加剧的当下，你想法的质量比以往任何时候都更重要。</li><li>创造性生活的4个模块，以及一份用来规划你一周的模板。</li><li>知名创作者们的日常日程，以及查尔斯·达尔文（Charles Darwin）如何用极少的工作量改变了世界。</li><li>我个人的日常日程，我为什么这样做，以及如何打造属于你自己的日程。</li></ul><p>话虽如此，这份newsletter是写给那些<em>想要</em>那种杠杆的人的。这不是写给那些执意坚持更传统工作方式的人的。我不是来说服你的，我只是在说明，这篇文章你可能未必能从中获益。</p><p>你工作的质量取决于你想法的质量。因此，生产力的未来就是创造力。而随着经济持续偏向那些善用AI和技术的创作者与创始人，我们工作的方式正在改变。</p><p>生产力的未来就是创造力。</p><h2 id="想法的流动比以往任何时候都更重要" tabindex="-1">想法的流动比以往任何时候都更重要 <a class="header-anchor" href="#想法的流动比以往任何时候都更重要" aria-label="Permalink to &quot;想法的流动比以往任何时候都更重要&quot;">​</a></h2><p>任何人都可以在浏览器里输入ChatGPT，让它吐出一本书、一份newsletter、一份营销素材、一件艺术品、一个待办事项应用的代码，或者一份法律文件。</p><p>然而，并没有出现一百万本�(品质达到)畅销书水准的书籍，或者生产级的软件。工作变得容易了，但大多数人缺乏能动性这个事实依然存在。如果在过去10年里，人们本来就没有动力去打造自己的东西，那他们现在依然不会有动力，甚至可能被那些有动力的人利用。</p><p>我可能大错特错。但我不认为AI能取代作家。我说“作家”时，指的不是这个头衔。我指的也不是某人用来创作的<em>工具</em>。我指的是写作背后的本质。</p><ul><li>从100个想法中筛选出1个</li><li>围绕一个目标构建一条创造性的叙事</li><li>吸引一群人的注意力</li><li>通过<em>有意识的体验</em>与他们建立深层的联系</li><li>为后代记录高信号的信息</li></ul><p>话说回来，我丝毫不反对AI。</p><p>事实上，我们正在<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>里实现它，接下来这个月就会上线（挺酷的）。</p><p>问题在于，如果你不是一个作家，或者不向作家学习，你的AI产出很可能会让你失望。如果（1）你不知道自己想造什么，（2）即便AI让事情变得更容易，你还是懒得去学（尽管过去10年这件事本来就不难），那祝你好运，看你能不能“造出点什么”。如果在人生的任何领域取得惊人成功本来需要10年，而AI把它压缩到5年（甚至1年），这也改变不了一个事实：大多数人两周就放弃了。世界会加速前进，而这会吓坏那些心智准备不足的人。</p><p>AI缺乏执行功能。</p><p>它是一个需要主人的工具。一个需要通才来驾驭的专才。而当那么多人已经被自己的父母、学校教育和重复性的任务型工作训练成了“工具”，人们如此害怕被取代也就不奇怪了。这是因为他们<em>确实</em>会被取代——除非他们开始像一个真正的人那样行动。能动性。有意识的体验。风险。犯错。探索。感知。</p><p>举个例子，詹姆斯·帕特森（James Patterson）在写小说时会用代笔作家。</p><p>作者詹姆斯本人依然负责构思情节、确定语气、写作风格和最终成品，并对分发、销售、社群等所有相关事宜保有全局性的把握。</p><p>一个代笔作家，或者AI，能省去创作这些文字，以及把它呈现给他人所需的辅助性劳动所耗费的时间和精力。但那个“主人”依然必须是个通才。他们依然必须是个企业家。他们依然需要愿景、故事和价值。</p><p>但你要怎么让这些东西产生真正的影响力呢？</p><p>你不能直接让ChatGPT吐出一个愿景、一个故事、一种价值吗？</p><p>你可以，但除非你甘愿受<em>AI默认写作方式（那种内建的偏见）</em>的摆布，你依然会和大多数人做着一样的事。你依然会缺乏能动性。你会被归入那种带有偏见模型产出的同质化内容之中，而按市场规律来说，你会沦为一种大宗商品。你将无法<em>持续获得</em>任何有意义的结果。</p><p>答案在于想法的流动。</p><p>罗伯特·格林（Robert Greene）在写一本书之前会读100本书。</p><p>创始人们要经历1000个想法，才有1个能改变一切。</p><p>创作者们要发1000次内容，才有1次让他们一夜成名。</p><p>更多的想法会带来更多的指数级事件。什么都没发生，然后一切都发生了。</p><p>你不会靠让ChatGPT给你列一份100个想法的清单来找到这些点子。因为你猜怎么着，你<em>依然缺少那个宏观的愿景和故事。</em></p><p><em>你缺少经历。你缺少意义。你缺少目的。</em></p><p><em>你缺少一种向前推进的生活方式——一种为了实现你的愿景而设计出来的生活方式，从中你才能提取并连接各种想法来创造价值。你缺少的是背景/情境。</em></p><p>人们关注你，不是因为你有信息，而是因为你有<em>故事底蕴（lore）</em>。如果我的社交feed全被那些默认的、AI生成的千篇一律的“声音”填满，我的手机早就沉到湖底了。正如人们不信任那个体制一样，他们也不会信任AI，而一个志同道合的部落，才是你能找到意义的地方。受众依然是你能建立的最重要的东西之一。你依然就是那个细分领域本身。尤其是在加密技术能让你验证和拥有你的作品的情况下——无论你是否使用AI，都是如此。</p><p>沿着发展的螺旋不断上升，钟摆正在摆回我们祖先那种部落式的天性。</p><h2 id="创造性生活方式设计的4c法则" tabindex="-1">创造性生活方式设计的4C法则 <a class="header-anchor" href="#创造性生活方式设计的4c法则" aria-label="Permalink to &quot;创造性生活方式设计的4C法则&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>当我说自己每天只工作4小时时，人们的脸上总会露出一种奇怪的表情。</p><p>表面上看，我好像完成了很多事情。每天在所有平台上发帖。每周一份newsletter和一段YouTube视频。管理和搭建Kortex。写一本书。做产品。一堆事情。</p><p>我的问题是：我做的这些事情，到底哪里疯狂了？</p><p>我是说，天啊，当我刚开始积累受众的时候，我是在打游戏的间隙写帖子、跟人聊天的。如果我认真算算实际工作的时间，大概每天也就一个小时。我曾经拖延症极其严重，这反而逼着我只专注在真正重要的事情上。</p><p>即便到现在，我也是把写书、写每周newsletter、写社交媒体帖子，全部塞进早晨的头两个小时里。如果我没在写书，那我就在打造另一个产品或项目。这些是我的基本杠杆点。只要这些做完了，我这一天的“工作”就算完成了。</p><p>有时候，我想要造出点什么的欲望会变得非常强烈。我控制不住自己，会连续工作8到12个小时。问题是，这种高强度冲刺的季节是我无法强行制造出来的。它是一种自然而然积累出来的清晰感——通过不断把精力投入某个愿景之中——直到我除了全力冲刺别无选择。</p><p>我们稍后会讲讲我日常日程的其余部分。</p><p>但是，是的，我得承认，这里面藏着一个小小的谎言。</p><p>我其实从未真正把阅读、散步、打盹或训练算作我“工作”的一部分。我阅读是为了寻找想法。我散步是为了理清那些想法。我打盹是因为我喜欢打盹。我训练是因为我享受精力充沛和健康的感觉。</p><p>如果我不做这些事情，我工作的质量和数量根本不可能实现。我不是在优化“做得更多”，我是在优化那个能带来我实现目标所需成果的“恰当分量”。凭借这些简单的习惯，我能用更少的“工作”产生比大多数每天工作12小时的人更大的影响力。再说一次，创造力才是生产力的燃料。</p><p>所以，如果把这些都算进我“工作”的时长里，那我其实是每天、全天都在工作，因为我的工作就是我的使命。它是我生命中最重要的事情。</p><p>话虽如此，你严重高估了起步所需要投入的工作量。理性一点想一想。你<em>知道</em>别人也和你一样有各种责任。你<em>知道</em>人们不是一开始就工作12个小时的，他们一开始只是早上工作1个小时。你只是喜欢找各种理由，说自己的情况有多特殊。</p><p>现在的问题是：我该如何把那专注的1小时工作用到极致？</p><p>办法是设计一种创造性的生活方式，并随着你有能力转向全职投入，逐步把花在这些活动上的时间往上调。</p><p>你需要4个习惯。</p><p>把它们想象成你一天中的几个模块。你不必按顺序做它们，你只需要把它们都做到就行。</p><p>如果你愿意，这里有<a href="https://app.kortex.co/public/document/e930cde4-6021-47e8-b25f-085c8679e9f7" target="_blank" rel="noreferrer">一份新的每周计划表</a>，它会带你每天走一遍这些步骤（还附带一个记录每日任务的地方）。</p><h3 id="习惯1-清空-clear" tabindex="-1">习惯1：清空（Clear） <a class="header-anchor" href="#习惯1-清空-clear" aria-label="Permalink to &quot;习惯1：清空（Clear）&quot;">​</a></h3><p>我最喜欢的清空大脑的方法，是把负面的想法和经历，转化成5到10个可以用在我工作中的点子。</p><p>我通常在早上开始写作之前先做这件事（严格来说，这本身也是一种写作），但我也认识很多人是在睡前做这件事，这样他们早上起来就有可以写的东西了。</p><p>对着一张空白页坐下来，探问你的内心。</p><p>想法可能不会马上出现，但它们终会出现。</p><p>另一种清空大脑的方法，是一个简单的“大脑倾倒”日记。</p><ul><li>把你脑子里能挤出来的一切，一字不落地写下来</li><li>把它们分门别类整理好（比如工作、烦恼，以及不重要的事）</li></ul><p>这个目标并不是要对这些想法“做”什么。目标是觉察，因为觉察本身具有自我修正的作用。</p><h3 id="习惯二-吸收" tabindex="-1">习惯二：吸收 <a class="header-anchor" href="#习惯二-吸收" aria-label="Permalink to &quot;习惯二：吸收&quot;">​</a></h3><p>简单直白地说：</p><p>如果你不吸收，你就无法创造。</p><p>我说的不是像个没有思想的僵尸那样在社交媒体上无休止地刷内容。我说的是<em>学习</em>。为你的工作猎取想法。就像你的祖先在现实中狩猎一样，你现在要在心智和数字世界中狩猎。</p><ul><li>读一本长书</li><li>读一篇长文章</li><li>花5分钟刷一个精选过的社交时间线</li><li>学习那门你买了却忘掉的课程</li><li>听一个播客或讲座</li></ul><p>但别忘了一个绝对关键的步骤：要有一个地方，把这些想法捕捉进你正在创作的相关项目中。</p><p>在Kortex中，你可以用“Capture（捕捉）”功能来做这件事。写下想法，输入“@文档名称”，就能把它保存到指定的项目中。市面上没有其他捕捉工具能做到这一点。<a href="https://youtu.be/nktY727HVKQ" target="_blank" rel="noreferrer">我在这里详细讲解了这个流程，并给你一个每周内容模板。</a></p><p>重点是：如果你不学习……那你就是不学习。因此，你就无法在生活中向前迈进，也无法开启新的机会。</p><h3 id="习惯三-创造" tabindex="-1">习惯三：创造 <a class="header-anchor" href="#习惯三-创造" aria-label="Permalink to &quot;习惯三：创造&quot;">​</a></h3><p>人类的核心渴望是创造、扩展和超越。</p><p>其他任何事情，都不过是分心的事，或是把你拉向这些渴望的次要目的。</p><p>“创造”是在照顾心智一个大多数人都忽略了的关键功能。</p><p>每个人都在吸收信息（他们在积累心智上的脂肪）。有些人会把信息写下来（他们在削减心智上的重量）。但很少有人会把这些信息综合提炼成能帮助并影响他人的东西（他们才拥有在一场心智车祸中救人的力量）。</p><p>换句话说，大多数人不知道自己该如何为世界做出贡献。他们缺失了目的感。是深层的目的，不是肤浅的那种。</p><p>你需要一个可以持续建设的项目。</p><p>一个能让你从中连接各种想法的心智结构。</p><h3 id="习惯四-连接" tabindex="-1">习惯四：连接 <a class="header-anchor" href="#习惯四-连接" aria-label="Permalink to &quot;习惯四：连接&quot;">​</a></h3><p>当你有一个有意义的项目去建设——不是父母、老师或社会大众强加给你的那种——你看待生活的方式会完全不同。</p><p>当我写一本书时，显然，这和写一条社交动态完全不同。</p><p>我的心智会扩展，<em>以匹配那本书的框架</em>。</p><p>我在日常经历、吸收的信息以及进行的对话中，注意到的东西更多了，因为我为这些想法有了一个<em>锚点</em>。</p><p>我的心智可以飞速穿越复杂的推理，理解我以前无法理解的想法。我能够表达出AI无法表达的全新思路，因为要让AI接近这一点，我得先用同样的框架去训练它。</p><p>不幸的是，大多数人并没有针对模式识别进行优化（这正是这个4C框架能帮上忙的地方）。因此，他们很少变得好奇或痴迷。他们没有把精力投入到一个能促使自己心智塑造出新形态的项目中。</p><h2 id="我如何、以及为何以某种特定方式安排和平衡我的深度工作时间段" tabindex="-1">我如何、以及为何以某种特定方式安排和平衡我的深度工作时间段 <a class="header-anchor" href="#我如何、以及为何以某种特定方式安排和平衡我的深度工作时间段" aria-label="Permalink to &quot;我如何、以及为何以某种特定方式安排和平衡我的深度工作时间段&quot;">​</a></h2><blockquote><p>终极目标是拥有一种设计得如此精美的生活，以至于工作、休息和娱乐不再有区别。你生命的全部都被引流进一个单一却不断演化的愿景之中。</p></blockquote><p>工作没有唯一正确的方式。</p><p>显然，霍尔莫兹（Hormozi）一天工作12小时也过得很好，而世界上许多最著名的创意人几乎几乎不怎么工作。</p><p>重点在于实验。收集各种视角，去亲身体验它们，然后舍弃那些不适合你独特目标、兴趣和价值观的部分。这被称为生活方式<em>设计</em>，是有原因的。你不能简单地照搬别人的设计，就期望它能让你变富。如果你连创造性过程都无法应用到影响一切的这件最主要的事情上，你还怎么称自己是个创作者呢？</p><p><img src="'+r+'" alt=""></p><p>我想着重讲一讲查尔斯·达尔文（Charles Darwin）的日常作息，因为它反映了我自己作息背后的很多原因。达尔文的日常作息高度结构化，包含多次散步和多个书房工作时段。</p><p>早晨，他在早上7点以一段短短的散步开始新的一天，随后是早餐。接着他会开始第一个——<em>最高效的</em>——工作时段，从早上8点到9点半。工作结束后，达尔文会休息一下，读读信件、陪陪家人，然后再回来进行另一个工作时段，从上午10点半到中午。到这个时候，他就已经觉得自己“完成了一天不错的工作”。</p><p>然后，达尔文会进行他一天中的第二次散步，沿着他那条著名的“沙径”（Sandwalk）——一条长四分之一英里的碎石路，是达尔文<em>专门为思考和反思而修建的</em>。午餐、读报之后，达尔文会休息一下，听妻子朗读。下午4点，他进行一天中的第三次散步，通常还是沿着沙径，有时会有人陪伴。</p><p>我跟你分享这些的重点是：查尔斯·达尔文，恰恰这样一个人，工作时间少得惊人，然而他一生中完成的成就却比今天大多数痴迷于生产力的人还<em>多</em>。</p><p>这一认知至关重要，因为它能让你把“工作时长”和“产出的成果”这两者剥离开，你就能开始去<em>思考</em>、去<em>实验</em>你自己的一天，而不是照搬一个为别人的目标而设计的模式，那些目标并不是你自己的。</p><p>你可能已经猜到了，我最喜欢达尔文作息中的一点，是<a href="/letters/the-power-of-long-walks-daily-walks-will-change-your-life">散步的重要性</a>。那些深度思考的时刻是他工作中不可或缺的一部分。专注的工作时段搭配规律的散步，让他能够在高强度的智力工作与休息、沉思的时间之间取得平衡。想象一下，如果他当时就能用上AI会怎样。</p><p>达尔文写了<em>19（！）本书</em>，并通过这种方式发展出了他的进化论。</p><h3 id="我的作息——释放并约束熵" tabindex="-1">我的作息——释放并约束熵 <a class="header-anchor" href="#我的作息——释放并约束熵" aria-label="Permalink to &quot;我的作息——释放并约束熵&quot;">​</a></h3><p>我喜欢把我的一天切成3个部分：</p><ul><li><strong>低熵</strong> —— 几乎没有不确定性或混乱的空间。心思清晰，深度专注，高度有意向。</li><li><strong>中熵</strong> —— 允许自己与人互动、与手机互动。</li><li><strong>高熵</strong> —— 受控的混乱，会产生大量我可以在第二天早上加以利用的想法。</li></ul><p>我通常自然醒于早上5点左右，有时更早。在天气暖和的月份，我起床后第一件事就是去散步10到20分钟。在天气冷的月份，我发现直接投入工作对我来说更好。冬天更像是一个“建设”的季节。当我确实去散步时，我只是专注于<em>回来之后要写什么</em>。</p><p>我的第一个90分钟工作时段专门用于我杠杆效益最高的任务。通常这是一本书、一款产品，或一项业务——某种只需要建设一次、而不需要系统化并永久维护的东西。现在，我在写我的第二本书。这也是我把一天中“清空大脑”这个模块嵌入进去的时候，如果需要的话，我会头脑风暴出5到10个相关的想法。</p><p>吃一顿简单便捷的早餐后（通常只是水果，以免拖慢我的思维），我的第二个工作时段持续45到90分钟不等。这时我会做那些能让我的工作增长和维持的高优先级任务。对我来说，这包括写一份通讯的某一部分（20到45分钟），尽可能写出更多内容创意（10到30分钟），以及跨平台转发内容（大约15分钟）。这非常取决于我的大脑当天产出想法的效率如何。星期二，我会把这个时段换成录制视频。我也在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>这门课里教授这个流程。</p><p>注：这也是我在Kortex中的主要职责。我负责引流并执行增长策略。</p><p>对于那些对此有疑问的人，是的，我每天都写我的通讯和内容。我不喜欢“主题日”这种安排。我每天训练。每天写作。以及做任何我认为是生活中重要部分的事情——每天都做。哪怕在假期。哪怕在节日期间。这才是带给我快乐、让我保持清醒的东西。</p><p>结束那个工作时段、再吃点水果之后，我也会像达尔文一样，感觉自己已经完成了一天不错的工作。这时，我会进行第二次散步，通常光着上身，去晒晒正午的太阳（这对许多健康方面的问题都有帮助），并顺带消耗一些有声书、视频、讲座，或者有时干脆直接用手机阅读。这是我目前正在写的内容中，最好的想法涌现的时刻。我会把所有想法捕捉下来，并在Kortex Capture中把它们连接到相关的项目（这样它们就不会丢失）。</p><p>散步之后，有时甚至在散步过程中，我会处理一些行政性事务，比如回复邮件、给合作伙伴发消息，以及查看<a href="https://kortex.co/premium" target="_blank" rel="noreferrer">高级会员Discord</a>。</p><p>然后，我去健身房。由于我每天训练，训练量分摊到7天中，所以每次训练时间都相当短——最多30到40分钟。高强度。躯干、手臂、腿部，循环往复。每个肌群4组。大多是交替部位的超级组。健身之后，我会吃一顿蛋白质含量更高的午餐。</p><p>健身房标志着我一天中一个关键的分界点。这是我从工作过渡到接下来几个小时轻度休息的地方。在这个阶段，我基本不再追踪时间。回到家后，我会做我心里想做的事：散步、阅读、打个盹、灵感来了就写一点，给人发消息。这是我安排大多数会议或通话的时间。当我处于高强度冲刺的阶段时，这几个小时通常会被用来建设那个需要我全神贯注的项目。</p><p>大约5点的时候，我会和我的编辑和/或女朋友一起去吃晚餐。周六是约会之夜。除非有什么极其紧迫的事情必须要做，否则这之后我不再工作。如果我觉得无聊，我可能会再去散一次步，但大多数时候我会非常懒散。一开始，让自己这样放松、<em>停止</em>专注于工作，其实挺难的。</p><p>晚上9点到10点之间上床睡觉。</p><p>就是这样。这就是我的生活。</p><p>我希望它能以某种方式给你一些启发。</p><p>至少，如果我能提供一件你可以拿来实验的东西，我就已经很感激了。</p><p>——丹（Dan）</p><hr><p><a href="/en/letters/the-future-of-productivity-a-daily-routine-to-organize-your-uncertain-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',122))])}const x=i(c,[["render",h]]);export{A as __pageData,x as default};
